
from pydantic import BaseModel, Field


class ActionParameters(BaseModel):
    """Parameters extracted from the user's command."""

    query: str | None = None
    reference: str | None = None
    direction: str | None = None


class PlanStep(BaseModel):
    """One action in an ordered action plan."""

    action: str = Field(
        description="Exact action name from the available website skill."
    )

    parameters: ActionParameters = Field(
        default_factory=ActionParameters
    )


class PlannerOutput(BaseModel):
    """Structured response generated by Gemini."""

    intent: str = Field(
        description="Short description of the user's intention."
    )

    needs_clarification: bool = Field(
        default=False,
        description="True if the user's request is ambiguous or missing information."
    )

    clarification_question: str | None = Field(
        default=None,
        description="Question to ask the user if clarification is needed."
    )

    steps: list[PlanStep] = Field(
        default_factory=list,
        description="Ordered list of actions to perform."
    )


class ActionPlan(BaseModel):
    """Plan enriched with trusted website context."""

    website: str
    intent: str
    needs_clarification: bool = False
    clarification_question: str | None = None
    steps: list[PlanStep] = Field(default_factory=list)


class PlannerRequest(BaseModel):
    """Request received by the planner API."""

    command: str = Field(min_length=1)

    context: dict

    page_metadata: dict = Field(
        default_factory=dict
    )

    session_state: dict = Field(
        default_factory=dict
    )
